                ctx.beginPath();
                ctx.moveTo(-earDist - earSize / 2, -earSize * 0.3);
                ctx.lineTo(-earDist, -earSize * 1.3);
                ctx.lineTo(-earDist + earSize / 2, -earSize * 0.3);
