                ctx.beginPath();
                ctx.moveTo(-earDist - earSize * 0.25, -earSize * 0.4);
                ctx.lineTo(-earDist, -earSize * 1.05);
                ctx.lineTo(-earDist + earSize * 0.25, -earSize * 0.4);
