                // Right Lens
                ctx.beginPath();
                ctx.roundRect(glassW * 0.04, -glassH / 2, glassW * 0.42, glassH, 14);
                ctx.fill();
                ctx.stroke();
                // Bridge
                ctx.beginPath();
                ctx.moveTo(-glassW * 0.04, -glassH * 0.15);
                ctx.lineTo(glassW * 0.04, -glassH * 0.15);
                ctx.stroke();
